# Минимальный HTTP-сервер с эндпоинтом `/health`

Приведу примеры на нескольких языках — выбирай под свой стек.

## Python (стандартная библиотека, без зависимостей)

```python
from http.server import BaseHTTPRequestHandler, HTTPServer
import json

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/health":
            body = json.dumps({"status": "ok"}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, *args):
        pass  # отключаем лишний лог

if __name__ == "__main__":
    HTTPServer(("0.0.0.0", 8000), Handler).serve_forever()
```

Запуск: `python server.py` → `curl http://localhost:8000/health`

## Go (стандартная библиотека)

```go
package main

import (
	"encoding/json"
	"net/http"
)

func main() {
	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})
	http.ListenAndServe(":8000", nil)
}
```

Запуск: `go run main.go`

## Node.js (без зависимостей)

```javascript
const http = require("http");

const server = http.createServer((req, res) => {
  if (req.method === "GET" && req.url === "/health") {
    const body = JSON.stringify({ status: "ok" });
    res.writeHead(200, {
      "Content-Type": "application/json",
      "Content-Length": Buffer.byteLength(body),
    });
    res.end(body);
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(8000, () => console.log("Listening on :8000"));
```

Запуск: `node server.js`

## Что важно для `/health`

- **HTTP 200** при живом сервисе (для балансировщиков/k8s liveness probe).
- **Короткое время ответа** — без походов в БД, если это liveness-проба.
- **Фиксированный формат ответа** (`{"status":"ok"}`) — чтобы мониторинг мог парсить.
- Если нужно проверять зависимости (БД, кэш) — это уже **readiness**-проба, и её логично вынести в отдельный эндпоинт, например `/ready`.

Какой язык/стек тебе нужен — могу уточнить под него (FastAPI, Express, Gin и т.д.).

ИТОГ: Dependency injection (DI) — это приём, при котором объект не создаёт свои зависимости сам, а получает их извне.

Простыми словами: вместо того чтобы внутри функции/структуры писать `NewDB()`, ты передаёшь уже готовый `db` как параметр. Тогда код знает не «как создать зависимость», а только «что она умеет».

Зачем это нужно:
- **Слабая связанность**: код зависит от интерфейса, а не от конкретной реализации.
- **Тестируемость**: в тестах подставляешь мок/заглушку вместо реальной БД, сети и т.п.
- **Гибкость**: можно подменить реализацию без правок вызывающего кода.
- **Явность**: зависимости видны в сигнатуре, а не спрятаны внутри.

Пример на Go (только стандартная библиотека). Зависимость описываем интерфейсом и внедряем через конструктор:

```go
package main

import (
	"errors"
	"fmt"
)

// Интерфейс — то, что умеет зависимость.
type UserStore interface {
	GetName(id int) (string, error)
}

// Бизнес-логика зависит от интерфейса, а не от конкретной реализации.
type UserService struct {
	store UserStore
}

// Внедрение зависимости через конструктор.
func NewUserService(store UserStore) *UserService {
	return &UserService{store: store}
}

func (s *UserService) Greet(id int) (string, error) {
	name, err := s.store.GetName(id)
	if err != nil {
		return "", err
	}
	return "Привет, " + name, nil
}

// Продакшн-реализация.
type memoryStore struct {
	data map[int]string
}

func NewMemoryStore() *memoryStore {
	return &memoryStore{data: map[int]string{1: "Аня"}}
}

func (m *memoryStore) GetName(id int) (string, error) {
	name, ok := m.data[id]
	if !ok {
		return "", errors.New("пользователь не найден")
	}
	return name, nil
}

// Тестовая заглушка.
type fakeStore struct{}

func (fakeStore) GetName(id int) (string, error) {
	return "Тест", nil
}

func main() {
	// В проде внедряем реальную реализацию.
	svc := NewUserService(NewMemoryStore())
	msg, _ := svc.Greet(1)
	fmt.Println(msg)

	// В тесте — заглушку.
	testSvc := NewUserService(fakeStore{})
	testMsg, _ := testSvc.Greet(1)
	fmt.Println(testMsg)
}
```

Способы внедрения:
- **Через конструктор** (самый частый в Go).
- **Через параметры метода** (когда зависимость нужна только одной операции).
- **Через поле/сеттер** (реже, удобно для опциональных зависимостей).

В Go DI обычно делают «руками»: явно собираешь граф зависимостей в `main`. DI-фреймворки существуют, но в идиоматичном Go часто обходятся без них.

