ИТОГ: Dependency Injection (DI) — это приём, при котором объект не создаёт свои зависимости сам, а получает их извне, что уменьшает связанность кода и упрощает тестирование и замену компонентов.

Проще говоря, вместо того чтобы внутри функции жёстко создавать нужный объект, вы передаёте его как параметр. В Go это особенно естественно, потому что зависимости обычно оформляются как интерфейсы, а конкретные реализации подставляются на уровне `main` или в конструкторе.

Пример без DI — функция сама создаёт зависимость:

```go
package main

import (
	"fmt"
	"io"
)

type Notifier interface {
	Send(msg string) error
}

type ConsoleNotifier struct {
	out io.Writer
}

func (c ConsoleNotifier) Send(msg string) error {
	_, err := fmt.Fprintln(c.out, msg)
	return err
}

type Service struct{}

func (s Service) Do() {
	n := ConsoleNotifier{} // жёстко создаём зависимость
	_ = n.Send("hello")
}
```

Здесь `Service` жёстко привязан к `ConsoleNotifier`, его сложно протестировать и заменить.

Пример с DI — зависимость передаётся снаружи:

```go
package main

import (
	"fmt"
	"io"
	"os"
)

type Notifier interface {
	Send(msg string) error
}

type ConsoleNotifier struct {
	out io.Writer
}

func (c ConsoleNotifier) Send(msg string) error {
	_, err := fmt.Fprintln(c.out, msg)
	return err
}

type Service struct {
	notifier Notifier
}

func NewService(n Notifier) *Service {
	return &Service{notifier: n}
}

func (s *Service) Do() error {
	return s.notifier.Send("hello")
}

func main() {
	n := ConsoleNotifier{out: os.Stdout}
	s := NewService(n)
	if err := s.Do(); err != nil {
		fmt.Fprintln(os.Stderr, err)
	}
}
```

Теперь `Service` зависит только от интерфейса `Notifier`. В тестах можно подставить фейковую реализацию:

```go
type fakeNotifier struct {
	last string
}

func (f *fakeNotifier) Send(msg string) error {
	f.last = msg
	return nil
}
```

Ключевые преимущества DI:
- слабая связанность: код зависит от абстракций, а не от конкретных типов;
- тестируемость: легко подменять зависимости заглушками;
- гибкость: одну и ту же логику можно использовать с разными реализациями;
- явность: зависимости видны в сигнатурах конструкторов и функций.

В Go DI обычно делают вручную через конструкторы, без сторонних фреймворков; иногда применяют функциональные опции, если параметров много.

# Минимальный HTTP-сервер с эндпоинтом `/health`

## Python (стандартная библиотека)

```python
from http.server import BaseHTTPRequestHandler, HTTPServer
import json

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path == "/health":
            body = json.dumps({"status": "ok"}).encode()
            self.send_response(200)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        else:
            self.send_response(404)
            self.end_headers()

    def log_message(self, *args):
        pass  # отключаем логирование в stderr

if __name__ == "__main__":
    HTTPServer(("0.0.0.0", 8000), Handler).serve_forever()
```

