import (
	"encoding/json"
	"log"
	"net/http"
)

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/health", healthHandler)

	log.Println("listening on :8080")
	if err := http.ListenAndServe(":8080", mux); err != nil {
		log.Fatal(err)
	}
}
```

Проверка:

```
go run main.go
curl -i http://localhost:8080/health
# HTTP/1.1 200 OK
# {"status":"ok"}
```

Метод не ограничен — `GET`, `HEAD` и прочие дадут тот же ответ. Если нужно ограничить только `GET`, добавь проверку `if r.Method != http.MethodGet { http.Error(w, "method not allowed", http.StatusMethodNotAllowed); return }` в начале хендлера.

